int evalRPN(char **tokens, int tokensSize) {
  int *stack = (int *)malloc(sizeof(int) * tokensSize);
  int top = 0;
  for (int i = 0; i < tokensSize; i++) {
    char *t = tokens[i];
    if (strcmp(t, "+") == 0 || strcmp(t, "-") == 0 || strcmp(t, "*") == 0 || strcmp(t, "/") == 0) {
      int b = stack[--top];
      int a = stack[--top];
      int r;
      if (t[0] == '+') {
        r = a + b;
      } else if (t[0] == '-') {
        r = a - b;
      } else if (t[0] == '*') {
        r = a * b;
      } else {
        r = a / b;
      }
      stack[top++] = r;
    } else {
      stack[top++] = atoi(t);
    }
  }
  int res = stack[top - 1];
  free(stack);
  return res;
}

class Solution {
public:
  int evalRPN(vector<string> &tokens) {
    vector<int> stack;
    for (const string &t : tokens) {
      if (t == "+" || t == "-" || t == "*" || t == "/") {
        int b = stack.back();
        stack.pop_back();
        int a = stack.back();
        stack.pop_back();
        int r = 0;
        if (t == "+") {
          r = a + b;
        } else if (t == "-") {
          r = a - b;
        } else if (t == "*") {
          r = a * b;
        } else {
          r = a / b;
        }
        stack.push_back(r);
      } else {
        stack.push_back(stoi(t));
      }
    }
    return stack.back();
  }
};

func evalRPN(tokens []string) int {
	stack := []int{}
	for _, t := range tokens {
		switch t {
		case "+", "-", "*", "/":
			b := stack[len(stack)-1]
			a := stack[len(stack)-2]
			stack = stack[:len(stack)-2]
			var r int
			switch t {
			case "+":
				r = a + b
			case "-":
				r = a - b
			case "*":
				r = a * b
			case "/":
				r = a / b
			}
			stack = append(stack, r)
		default:
			n, _ := strconv.Atoi(t)
			stack = append(stack, n)
		}
	}
	return stack[len(stack)-1]
}

class Solution {
  public int evalRPN(String[] tokens) {
    Deque<Integer> stack = new ArrayDeque<Integer>();
    for (String t : tokens) {
      switch (t) {
        case "+":
        case "-":
        case "*":
        case "/": {
          int b = stack.pop();
          int a = stack.pop();
          int r = 0;
          if (t.equals("+")) {
            r = a + b;
          } else if (t.equals("-")) {
            r = a - b;
          } else if (t.equals("*")) {
            r = a * b;
          } else {
            r = a / b;
          }
          stack.push(r);
          break;
        }
        default:
          stack.push(Integer.parseInt(t));
      }
    }
    return stack.pop();
  }
}

class Solution:
    def evalRPN(self, tokens: List[str]) -> int:
        stack = []
        for t in tokens:
            if t in ("+", "-", "*", "/"):
                b = stack.pop()
                a = stack.pop()
                if t == "+":
                    stack.append(a + b)
                elif t == "-":
                    stack.append(a - b)
                elif t == "*":
                    stack.append(a * b)
                else:
                    stack.append(int(a / b))
            else:
                stack.append(int(t))
        return stack[-1]

impl Solution {
  pub fn eval_rpn(tokens: Vec<String>) -> i32 {
    let mut stack: Vec<i32> = Vec::new();
    for t in tokens {
      match t.as_str() {
        "+" | "-" | "*" | "/" => {
          let b = stack.pop().unwrap();
          let a = stack.pop().unwrap();
          let r = match t.as_str() {
            "+" => a + b,
            "-" => a - b,
            "*" => a * b,
            _ => a / b,
          };
          stack.push(r);
        }
        _ => stack.push(t.parse::<i32>().unwrap()),
      }
    }
    stack.pop().unwrap()
  }
}

const evalRPN = (tokens: string[]): number => {
  const stack: number[] = [];
  const ops = new Set(["+", "-", "*", "/"]);
  for (const t of tokens) {
    if (ops.has(t)) {
      const b = stack.pop()!;
      const a = stack.pop()!;
      let r = 0;
      if (t === "+") r = a + b;
      else if (t === "-") r = a - b;
      else if (t === "*") r = a * b;
      else r = Math.trunc(a / b);
      stack.push(r);
    } else {
      stack.push(Number(t));
    }
  }
  return stack.pop()!;
};
